-- Reviewed senior batch 004; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":917,"word":"humanitarian","meaning":"人道的","example":"The students collected blankets and clean water for a humanitarian relief effort.","example_zh":"學生募集毛毯與乾淨飲水，投入人道救援工作。","original_meaning":"人道的","original_example":"Humanitarian aid.","original_example_zh":"人道主義援助。"},{"source_id":922,"word":"illusion","meaning":"幻覺","example":"The mirrors created the illusion of a hallway that never ended.","example_zh":"鏡子營造出走廊永無盡頭的錯覺。","original_meaning":"幻覺","original_example":"An optical illusion.","original_example_zh":"一種視覺錯覺。"},{"source_id":923,"word":"immune","meaning":"免疫的","example":"The classroom model shows how immune cells defend the body against germs.","example_zh":"教室裡的模型展示免疫細胞如何保護身體、抵禦病菌。","original_meaning":"免疫的","original_example":"Immune to the disease.","original_example_zh":"對該疾病免疫。"},{"source_id":926,"word":"implicit","meaning":"隱含的","example":"Without speaking, the teammates shared an implicit agreement to help the tired runner.","example_zh":"隊友沒有說話，卻默契十足地一起幫助疲憊的跑者。","original_meaning":"隱含的","original_example":"An implicit agreement.","original_example_zh":"一項默契。"},{"source_id":928,"word":"impulse","meaning":"衝動","example":"Mina resisted the impulse to buy another toy and saved her money instead.","example_zh":"米娜忍住再買一個玩具的衝動，把錢存了起來。","original_meaning":"衝動","original_example":"An impulse purchase.","original_example_zh":"衝動性購買。"},{"source_id":929,"word":"incentive","meaning":"激勵","example":"A basket of fresh vegetables gave the students an incentive to care for the garden.","example_zh":"一籃新鮮蔬菜讓學生更有動力照顧菜園。","original_meaning":"激勵","original_example":"Financial incentives.","original_example_zh":"財務獎勵。"},{"source_id":933,"word":"induce","meaning":"引起","example":"The smell of freshly baked bread can induce a feeling of hunger.","example_zh":"剛出爐麵包的香味可能引起飢餓感。","original_meaning":"引起","original_example":"Stress can induce illness.","original_example_zh":"壓力可能引發疾病。"},{"source_id":934,"word":"inferior","meaning":"低等的","example":"The inferior rope snapped while the stronger rope held the same weight.","example_zh":"品質較差的繩子斷了，較結實的繩子卻承受住相同重量。","original_meaning":"低等的","original_example":"An inferior product.","original_example_zh":"劣質產品。"},{"source_id":935,"word":"inflation","meaning":"通貨膨脹","example":"Because of inflation, the same coins bought fewer apples this year.","example_zh":"因為通貨膨脹，今年相同的硬幣只能買到較少的蘋果。","original_meaning":"通貨膨脹","original_example":"Rising inflation.","original_example_zh":"通膨上升。"},{"source_id":936,"word":"inhabit","meaning":"居住","example":"Many small creatures inhabit the pond behind our school.","example_zh":"許多小生物住在學校後方的池塘裡。","original_meaning":"居住","original_example":"Few people inhabit this island.","original_example_zh":"這座島嶼人口稀少。"},{"source_id":937,"word":"inherent","meaning":"固有的","example":"The guide explained the inherent risks of climbing a steep mountain.","example_zh":"嚮導解釋攀登陡峭山峰本身就有的風險。","original_meaning":"固有的","original_example":"An inherent risk.","original_example_zh":"固有的風險。"},{"source_id":938,"word":"inherit","meaning":"繼承","example":"Leo will inherit his grandfather's old violin and keep playing it.","example_zh":"里歐將繼承祖父的老提琴，並繼續拉奏它。","original_meaning":"繼承","original_example":"He inherited the house.","original_example_zh":"他繼承了這棟房子。"},{"source_id":939,"word":"initiate","meaning":"發起","example":"The science club will initiate a project to restore the school pond.","example_zh":"科學社將發起修復校園池塘的計畫。","original_meaning":"發起","original_example":"Initiate a conversation.","original_example_zh":"開啟對話。"},{"source_id":940,"word":"injustice","meaning":"不公","example":"The students spoke out against the injustice of excluding their new classmate.","example_zh":"學生發聲反對排擠新同學的不公平行為。","original_meaning":"不公","original_example":"Fight against injustice.","original_example_zh":"對抗不公。"},{"source_id":943,"word":"inspect","meaning":"檢查","example":"Before the trip, we inspect every bicycle for loose brakes.","example_zh":"旅行前，我們檢查每輛腳踏車的煞車是否鬆動。","original_meaning":"檢查","original_example":"Inspect the building.","original_example_zh":"檢查建築物。"},{"source_id":945,"word":"institute","meaning":"機構","example":"Our class visited a research institute to learn how scientists study the ocean.","example_zh":"我們班參訪研究機構，了解科學家如何研究海洋。","original_meaning":"機構","original_example":"A research institute.","original_example_zh":"一個研究機構。"},{"source_id":946,"word":"intact","meaning":"完整的","example":"Although the box was crushed, the glass vase inside remained intact.","example_zh":"雖然箱子被壓扁，裡面的玻璃花瓶仍完好無損。","original_meaning":"完整的","original_example":"The building remained intact.","original_example_zh":"建築物完好無損。"},{"source_id":947,"word":"intellect","meaning":"智力","example":"Solving the difficult puzzle challenged everyone's intellect.","example_zh":"解開這道難題考驗了每個人的智力。","original_meaning":"智力","original_example":"A person of great intellect.","original_example_zh":"一位才智過人的人。"},{"source_id":948,"word":"intensify","meaning":"加劇","example":"Dark clouds gathered as the wind began to intensify.","example_zh":"烏雲聚集，風也開始增強。","original_meaning":"加劇","original_example":"to intensify a photographic negative","original_example_zh":"加深底片曝光度"},{"source_id":949,"word":"interfere","meaning":"干涉","example":"Please do not interfere while the technician repairs the delicate model.","example_zh":"技師修理精密模型時，請不要干擾。","original_meaning":"干涉","original_example":"Do not interfere.","original_example_zh":"請勿干擾。"},{"source_id":951,"word":"intervene","meaning":"介入","example":"The teacher had to intervene when the argument became too heated.","example_zh":"爭論越來越激烈，老師不得不介入。","original_meaning":"介入","original_example":"The government intervened.","original_example_zh":"政府介入了。"},{"source_id":952,"word":"intimate","meaning":"親密的","example":"The small café was an intimate setting for a quiet family conversation.","example_zh":"這間小咖啡館適合一家人親密而安靜地談話。","original_meaning":"親密的","original_example":"An intimate relationship.","original_example_zh":"親密關係。"},{"source_id":955,"word":"invade","meaning":"入侵；闖入","example":"We built a fence to keep rabbits from trying to invade the vegetable garden.","example_zh":"我們圍起柵欄，防止兔子闖入菜園。","original_meaning":"入侵","original_example":"The army invaded the country.","original_example_zh":"軍隊入侵了該國。"},{"source_id":956,"word":"inventory","meaning":"庫存","example":"The volunteers checked the inventory before packing the food boxes.","example_zh":"志工在裝食物箱前先清點庫存。","original_meaning":"庫存","original_example":"Check the inventory.","original_example_zh":"檢查庫存。"},{"source_id":957,"word":"ironic","meaning":"諷刺的","example":"It was ironic that the umbrella shop had a leaking roof.","example_zh":"賣傘的店竟然屋頂漏水，真是諷刺。","original_meaning":"諷刺的","original_example":"An ironic twist.","original_example_zh":"一個諷刺性的轉折。"},{"source_id":962,"word":"keen","meaning":"渴望的","example":"Nora was keen to learn pottery and arrived before the class began.","example_zh":"諾拉很渴望學陶藝，課程開始前就到了。","original_meaning":"渴望的","original_example":"She is keen to learn.","original_example_zh":"她求知若渴。"},{"source_id":964,"word":"landmark","meaning":"地標","example":"The old clock tower is a landmark that helps visitors find the town square.","example_zh":"老鐘樓是地標，幫助遊客找到城鎮廣場。","original_meaning":"地標","original_example":"A famous landmark.","original_example_zh":"著名的地標。"},{"source_id":965,"word":"legislation","meaning":"立法","example":"The class discussed legislation that would protect the river from pollution.","example_zh":"班上討論了保護河川免於污染的相關立法。","original_meaning":"立法","original_example":"New legislation was passed.","original_example_zh":"新法案已通過。"},{"source_id":966,"word":"liberal","meaning":"開明的；自由的","example":"The liberal teacher encouraged students to explore different ways of making art.","example_zh":"思想開明的老師鼓勵學生探索不同的藝術創作方式。","original_meaning":"自由的","original_example":"Liberal democracy.","original_example_zh":"自由民主。"},{"source_id":967,"word":"likelihood","meaning":"可能性","example":"The dark clouds increased the likelihood of rain during our picnic.","example_zh":"烏雲讓我們野餐時下雨的可能性變高了。","original_meaning":"可能性","original_example":"The likelihood of success.","original_example_zh":"成功的可能性。"},{"source_id":968,"word":"literacy","meaning":"識字能力","example":"The volunteers support literacy by helping children read stories at the library.","example_zh":"志工在圖書館幫孩子讀故事，培養識字能力。","original_meaning":"識字能力","original_example":"Improve digital literacy.","original_example_zh":"提升數位素養。"},{"source_id":2489,"word":"abrupt","meaning":"突然的","example":"An abrupt gust of wind blew the papers off our picnic table.","example_zh":"一陣突如其來的風把野餐桌上的紙吹走了。","original_meaning":"突然的","original_example":"An abrupt change.","original_example_zh":"突如其來的變化。"},{"source_id":2490,"word":"acclaim","meaning":"讚譽","example":"The young violinist received acclaim after her moving performance.","example_zh":"年輕小提琴家在感人的演出後獲得讚譽。","original_meaning":"讚譽","original_example":"The film received acclaim.","original_example_zh":"這部電影廣受好評。"},{"source_id":2491,"word":"accord","meaning":"協議","example":"The two school clubs reached an accord to share the practice room.","example_zh":"兩個學校社團達成共用練習室的協議。","original_meaning":"協議","original_example":"In accord with the law.","original_example_zh":"符合法律規定。"},{"source_id":2492,"word":"accountable","meaning":"負責的","example":"Each team member is accountable for keeping the borrowed tools safe.","example_zh":"每位隊員都有責任妥善保管借來的工具。","original_meaning":"負責的","original_example":"Hold people accountable.","original_example_zh":"追究責任。"},{"source_id":2493,"word":"acute","meaning":"急性的；劇烈的","example":"An acute pain in his ankle made Leo stop running immediately.","example_zh":"腳踝的劇痛讓里歐立刻停止跑步。","original_meaning":"急性的","original_example":"Acute pain.","original_example_zh":"劇烈疼痛。"},{"source_id":2494,"word":"affiliate","meaning":"附屬","example":"The community orchestra plans to affiliate with a local music school.","example_zh":"社區管弦樂團計畫與當地音樂學校建立附屬關係。","original_meaning":"附屬","original_example":"Affiliated with the university.","original_example_zh":"隸屬於該大學。"},{"source_id":2495,"word":"aggravate","meaning":"加劇","example":"Walking on the injured ankle could aggravate the swelling.","example_zh":"用受傷的腳踝走路可能加重腫脹。","original_meaning":"加劇","original_example":"Do not aggravate the situation.","original_example_zh":"不要使情況惡化。"},{"source_id":2496,"word":"agony","meaning":"極度痛苦","example":"The runner sat in agony while the nurse examined his injured knee.","example_zh":"護理師檢查受傷的膝蓋時，跑者痛苦地坐著。","original_meaning":"極度痛苦","original_example":"In agony.","original_example_zh":"痛苦不堪。"},{"source_id":2497,"word":"albeit","meaning":"雖然","example":"The seedlings survived the storm, albeit with a few broken leaves.","example_zh":"幼苗撐過了暴風雨，雖然有幾片葉子折斷。","original_meaning":"雖然","original_example":"Albeit difficult, we succeeded.","original_example_zh":"儘管困難，我們還是成功了。"},{"source_id":2498,"word":"align","meaning":"對齊","example":"Use the ruler to align the edges of the wooden pieces.","example_zh":"用尺把木片的邊緣對齊。","original_meaning":"對齊","original_example":"Align your goals.","original_example_zh":"調整目標。"},{"source_id":2499,"word":"allude","meaning":"暗指","example":"During the interview, the actor began to allude to a surprise guest.","example_zh":"訪談時，演員開始暗示會有神祕嘉賓。","original_meaning":"暗指","original_example":"She alluded to the problem.","original_example_zh":"她暗示了這個問題。"},{"source_id":2500,"word":"amendment","meaning":"修正案","example":"The council proposed an amendment to make the school garden accessible to everyone.","example_zh":"委員會提出修正案，讓所有人都能方便使用校園花園。","original_meaning":"修正案","original_example":"A constitutional amendment.","original_example_zh":"一項憲法修正案。"},{"source_id":2501,"word":"apt","meaning":"恰當的","example":"The name Rainbow Garden was an apt choice for the colorful flower beds.","example_zh":"繽紛花圃取名為彩虹花園，是個恰當的選擇。","original_meaning":"恰當的","original_example":"An apt description.","original_example_zh":"恰如其分的描述。"},{"source_id":2502,"word":"articulate","meaning":"表達清楚的","example":"The articulate student explained the complex experiment in clear, simple language.","example_zh":"那位表達清楚的學生用簡單明白的語言解釋複雜實驗。","original_meaning":"表達清楚的","original_example":"She is very articulate.","original_example_zh":"她口才極佳。"},{"source_id":2503,"word":"astound","meaning":"使震驚","example":"The magician's final trick will astound the entire audience.","example_zh":"魔術師最後的戲法會讓全場觀眾驚嘆。","original_meaning":"使震驚","original_example":"The results astounded us.","original_example_zh":"結果令我們震驚不已。"},{"source_id":2504,"word":"avid","meaning":"熱切的","example":"As an avid reader, Mei always carries a novel in her backpack.","example_zh":"美是個熱愛閱讀的人，背包裡總帶著一本小說。","original_meaning":"熱切的","original_example":"An avid reader.","original_example_zh":"一位熱衷閱讀的人。"},{"source_id":2505,"word":"backlash","meaning":"反彈","example":"The plan to cut down the park's trees caused a strong public backlash.","example_zh":"砍掉公園樹木的計畫引發民眾強烈反彈。","original_meaning":"反彈","original_example":"A public backlash.","original_example_zh":"公眾的強烈反彈。"},{"source_id":2506,"word":"benchmark","meaning":"基準","example":"The first successful model became a benchmark for the students' later designs.","example_zh":"第一個成功的模型成為學生之後設計的基準。","original_meaning":"基準","original_example":"Set a benchmark.","original_example_zh":"樹立一個標竿。"},{"source_id":2507,"word":"boom","meaning":"繁榮","example":"The tourism boom brought more visitors to the seaside town.","example_zh":"觀光業的繁榮為海邊小鎮帶來更多遊客。","original_meaning":"繁榮","original_example":"An economic boom.","original_example_zh":"經濟繁榮。"},{"source_id":2508,"word":"boycott","meaning":"抵制","example":"The students decided to boycott products made with wasteful packaging.","example_zh":"學生決定抵制使用浪費包裝的產品。","original_meaning":"抵制","original_example":"Boycott the products.","original_example_zh":"抵制這些產品。"},{"source_id":2509,"word":"brisk","meaning":"輕快的","example":"We took a brisk walk around the lake before breakfast.","example_zh":"早餐前，我們在湖邊快步走了一圈。","original_meaning":"輕快的","original_example":"A brisk walk.","original_example_zh":"快步走。"},{"source_id":2510,"word":"calibrate","meaning":"校準","example":"We used a standard weight to calibrate the laboratory scale.","example_zh":"我們用標準砝碼校準實驗室的天平。","original_meaning":"校準","original_example":"Calibrate the instrument.","original_example_zh":"校準儀器。"},{"source_id":2511,"word":"candid","meaning":"坦率的","example":"Her candid comments helped us improve the uneven clay bowl.","example_zh":"她坦率的意見幫助我們改進那個不平整的陶碗。","original_meaning":"坦率的","original_example":"A candid opinion.","original_example_zh":"坦率的意見。"},{"source_id":2512,"word":"capacity","meaning":"容量","example":"The rain barrel reached its full capacity after the overnight storm.","example_zh":"一夜暴雨後，雨水桶達到最大容量。","original_meaning":"容量","original_example":"Full capacity.","original_example_zh":"滿載。"},{"source_id":2513,"word":"cascade","meaning":"瀑布","example":"A cascade of clear water tumbled over the rocks into the pool.","example_zh":"清澈的瀑布越過岩石，傾瀉進水潭。","original_meaning":"瀑布","original_example":"A cascade of events.","original_example_zh":"一連串的事件。"},{"source_id":2514,"word":"census","meaning":"人口普查","example":"A census worker visited each home to count the people living there.","example_zh":"人口普查員逐戶拜訪，統計住在各家的居民人數。","original_meaning":"人口普查","original_example":"A national census.","original_example_zh":"全國人口普查。"},{"source_id":2515,"word":"circumvent","meaning":"規避；繞過","example":"We used a side path to circumvent the flooded section of the trail.","example_zh":"我們走側邊的小路，繞過步道上淹水的路段。","original_meaning":"規避","original_example":"Circumvent the rules.","original_example_zh":"規避規則。"},{"source_id":2516,"word":"clarify","meaning":"澄清","example":"The teacher used a model to clarify how the bridge supports its weight.","example_zh":"老師用模型說明橋梁如何支撐重量。","original_meaning":"澄清","original_example":"Please clarify.","original_example_zh":"請說明清楚。"},{"source_id":2517,"word":"clash","meaning":"衝突","example":"The two teams began to clash over who could use the court first.","example_zh":"兩支隊伍為誰能先使用球場而發生衝突。","original_meaning":"衝突","original_example":"The two sides clashed.","original_example_zh":"雙方發生衝突。"},{"source_id":2518,"word":"clue","meaning":"線索","example":"A trail of muddy footprints gave us a clue to the puppy's hiding place.","example_zh":"一串泥腳印提供了線索，讓我們找到小狗的藏身處。","original_meaning":"線索","original_example":"Find a clue.","original_example_zh":"找出線索。"},{"source_id":2519,"word":"coalition","meaning":"聯盟","example":"The school clubs formed a coalition to protect the nearby wetland.","example_zh":"各校社團組成聯盟，保護附近的濕地。","original_meaning":"聯盟","original_example":"A political coalition.","original_example_zh":"政治聯盟。"},{"source_id":2520,"word":"cognitive","meaning":"認知的","example":"Matching shapes is a cognitive task that requires attention and memory.","example_zh":"配對形狀是一項需要注意力與記憶力的認知任務。","original_meaning":"認知的","original_example":"Cognitive ability.","original_example_zh":"認知能力。"},{"source_id":2521,"word":"commerce","meaning":"商業","example":"The busy harbor shows how commerce connects communities across the sea.","example_zh":"繁忙的港口展現商業如何連結海洋兩岸的社區。","original_meaning":"商業","original_example":"International commerce.","original_example_zh":"國際貿易。"},{"source_id":2522,"word":"commodity","meaning":"商品","example":"Rice is an important commodity traded in markets around the world.","example_zh":"稻米是世界各地市場交易的重要商品。","original_meaning":"商品","original_example":"A valuable commodity.","original_example_zh":"一種有價值的商品。"},{"source_id":2523,"word":"compatible","meaning":"相容的","example":"The new keyboard is compatible with the classroom computer.","example_zh":"新鍵盤與教室的電腦相容。","original_meaning":"相容的","original_example":"Compatible devices.","original_example_zh":"相容的裝置。"},{"source_id":2524,"word":"compulsory","meaning":"強制的","example":"Wearing a helmet is compulsory during the school's cycling activity.","example_zh":"參加學校的腳踏車活動時，必須戴安全帽。","original_meaning":"強制的","original_example":"Compulsory education.","original_example_zh":"義務教育。"},{"source_id":2525,"word":"concede","meaning":"承認","example":"After checking the score, the player had to concede defeat.","example_zh":"核對比分後，那位選手不得不承認落敗。","original_meaning":"承認","original_example":"He conceded defeat.","original_example_zh":"他承認敗北。"},{"source_id":2526,"word":"concise","meaning":"簡潔的","example":"Her concise explanation helped everyone understand the task quickly.","example_zh":"她簡潔的說明幫助每個人迅速理解任務。","original_meaning":"簡潔的","original_example":"A concise summary.","original_example_zh":"一份簡明扼要的摘要。"},{"source_id":2527,"word":"configure","meaning":"配置","example":"The technician helped us configure the projector for the school play.","example_zh":"技師幫我們設定校劇使用的投影機。","original_meaning":"配置","original_example":"Configure the settings.","original_example_zh":"設定參數。"},{"source_id":2528,"word":"conspicuous","meaning":"顯眼的","example":"The bright orange tent was conspicuous against the snowy mountain.","example_zh":"亮橘色帳篷在白雪覆蓋的山景中十分顯眼。","original_meaning":"顯眼的","original_example":"A conspicuous sign.","original_example_zh":"顯眼的標誌。"},{"source_id":2529,"word":"convene","meaning":"召集","example":"The club president will convene a meeting to plan the charity concert.","example_zh":"社長將召集會議，規劃慈善音樂會。","original_meaning":"召集","original_example":"Convene a meeting.","original_example_zh":"召開會議。"},{"source_id":2530,"word":"converge","meaning":"匯聚","example":"Three forest paths converge beside the old stone bridge.","example_zh":"三條森林小徑在老石橋旁交會。","original_meaning":"匯聚","original_example":"The roads converge here.","original_example_zh":"道路在此匯聚。"},{"source_id":2531,"word":"conviction","meaning":"定罪","example":"The court's conviction followed a careful review of the evidence.","example_zh":"法院仔細審查證據後作出有罪判決。","original_meaning":"定罪","original_example":"A strong conviction.","original_example_zh":"堅定的信念。"},{"source_id":2532,"word":"covert","meaning":"隱密的","example":"The classmates made covert preparations for their teacher's surprise party.","example_zh":"同學們偷偷準備老師的驚喜派對。","original_meaning":"隱密的","original_example":"A covert operation.","original_example_zh":"一項秘密行動。"},{"source_id":2533,"word":"culminate","meaning":"達到頂點","example":"Months of rehearsal will culminate in a performance at the town theater.","example_zh":"數月的排練將以在城鎮劇院演出作為成果。","original_meaning":"達到頂點","original_example":"Efforts culminated in success.","original_example_zh":"努力最終獲得成功。"},{"source_id":2534,"word":"curtail","meaning":"削減","example":"We decided to curtail water use by collecting rain for the garden.","example_zh":"我們決定收集雨水澆花，以減少用水。","original_meaning":"削減","original_example":"Curtail spending.","original_example_zh":"削減開支。"},{"source_id":2535,"word":"debris","meaning":"碎片","example":"Volunteers removed debris from the beach after the storm.","example_zh":"暴風雨後，志工清除海灘上的碎片與廢棄物。","original_meaning":"碎片","original_example":"Building debris.","original_example_zh":"建築廢料。"},{"source_id":2536,"word":"decree","meaning":"法令","example":"The royal decree protected the ancient forest from being cut down.","example_zh":"王室法令保護古老森林，禁止砍伐。","original_meaning":"法令","original_example":"A government decree.","original_example_zh":"一項政府法令。"},{"source_id":2537,"word":"defy","meaning":"違抗","example":"The climber refused to defy the guide's warning and stayed behind the barrier.","example_zh":"攀登者沒有違抗嚮導的警告，留在護欄後方。","original_meaning":"違抗","original_example":"Defy the rules.","original_example_zh":"違背規則。"},{"source_id":2538,"word":"delicate","meaning":"精緻的；易碎的","example":"Handle the delicate glass butterfly carefully so its wings do not break.","example_zh":"小心拿取精巧易碎的玻璃蝴蝶，別讓翅膀折斷。","original_meaning":"精緻的","original_example":"A delicate situation.","original_example_zh":"一個微妙的局面。"},{"source_id":2539,"word":"demographic","meaning":"人口的","example":"The museum's demographic display showed families of many ages in the town.","example_zh":"博物館的人口展示呈現鎮上各種年齡的家庭成員。","original_meaning":"人口的","original_example":"Demographic changes.","original_example_zh":"人口結構變化。"},{"source_id":2540,"word":"denounce","meaning":"譴責","example":"The students gathered to denounce cruelty toward abandoned animals.","example_zh":"學生聚集在一起，譴責虐待流浪動物的行為。","original_meaning":"譴責","original_example":"Denounce corruption.","original_example_zh":"譴責貪腐。"},{"source_id":2541,"word":"deplete","meaning":"耗盡","example":"Leaving the tap running can deplete the water stored in the tank.","example_zh":"讓水龍頭一直開著，可能耗盡水箱裡的水。","original_meaning":"耗盡","original_example":"Deplete resources.","original_example_zh":"耗盡資源。"},{"source_id":2542,"word":"detrimental","meaning":"有害的","example":"Too much artificial light can be detrimental to nesting sea turtles.","example_zh":"過多的人造光可能傷害築巢的海龜。","original_meaning":"有害的","original_example":"Detrimental effects.","original_example_zh":"有害影響。"},{"source_id":2543,"word":"devise","meaning":"設計","example":"Our team will devise a simple device to water the plants during the holiday.","example_zh":"我們小組將設計簡單裝置，在假期期間替植物澆水。","original_meaning":"設計","original_example":"Devise a strategy.","original_example_zh":"擬定策略。"},{"source_id":2544,"word":"diligent","meaning":"勤勉的","example":"The diligent student checked every measurement before building the model.","example_zh":"那位勤勉的學生在製作模型前仔細檢查每項尺寸。","original_meaning":"勤勉的","original_example":"A diligent student.","original_example_zh":"一位勤奮的學生。"},{"source_id":2545,"word":"discern","meaning":"辨別","example":"With the magnifying glass, we could discern tiny insects beneath the leaf.","example_zh":"透過放大鏡，我們能辨認葉片下的小昆蟲。","original_meaning":"辨別","original_example":"Discern the truth.","original_example_zh":"辨明真相。"},{"source_id":2546,"word":"disparity","meaning":"差距","example":"The display revealed a disparity in access to clean water between two villages.","example_zh":"展示揭示兩個村落取得乾淨飲水的差距。","original_meaning":"差距","original_example":"Income disparity.","original_example_zh":"收入差距。"},{"source_id":2547,"word":"dwell","meaning":"居住","example":"Several families dwell in the cottages beside the river.","example_zh":"幾戶人家住在河邊的小屋裡。","original_meaning":"居住","original_example":"Dwell on the past.","original_example_zh":"沉溺於過去。"},{"source_id":2548,"word":"eclipse","meaning":"日蝕","example":"We watched the solar eclipse through certified eclipse glasses.","example_zh":"我們戴著合格的日食觀測眼鏡觀看日食。","original_meaning":"日蝕","original_example":"A solar eclipse.","original_example_zh":"日食。"},{"source_id":2549,"word":"eloquent","meaning":"雄辯的","example":"Her eloquent speech inspired the audience to protect the forest.","example_zh":"她有說服力的演說激勵聽眾保護森林。","original_meaning":"雄辯的","original_example":"An eloquent speaker.","original_example_zh":"一位口才流利的演說家。"},{"source_id":2550,"word":"embark","meaning":"著手","example":"Our class will embark on a project to record the birds near our school.","example_zh":"我們班將開始進行記錄校園附近鳥類的計畫。","original_meaning":"著手","original_example":"Embark on a journey.","original_example_zh":"踏上旅程。"},{"source_id":2551,"word":"encompass","meaning":"包含","example":"The nature reserve will encompass the forest, lake, and surrounding wetlands.","example_zh":"自然保護區將涵蓋森林、湖泊及周圍濕地。","original_meaning":"包含","original_example":"The plan encompasses everything.","original_example_zh":"該計畫涵蓋一切。"},{"source_id":2552,"word":"enrich","meaning":"豐富","example":"Working with students from other countries can enrich our understanding of the world.","example_zh":"與其他國家的學生合作能豐富我們對世界的了解。","original_meaning":"豐富","original_example":"Enrich your life.","original_example_zh":"豐富你的生活。"},{"source_id":2553,"word":"entail","meaning":"需要","example":"Building the greenhouse will entail measuring, cutting, and assembling the frame.","example_zh":"建造溫室需要丈量、切割及組裝框架。","original_meaning":"需要","original_example":"What does it entail?","original_example_zh":"這意味著什麼？"},{"source_id":2554,"word":"erupt","meaning":"爆發","example":"The model volcano will erupt when we mix the ingredients.","example_zh":"混合材料後，火山模型就會噴發。","original_meaning":"爆發","original_example":"The volcano erupted.","original_example_zh":"火山爆發了。"},{"source_id":2555,"word":"exacerbate","meaning":"惡化","example":"Hot, dry winds can exacerbate the effects of a drought.","example_zh":"炎熱乾燥的風可能加劇乾旱的影響。","original_meaning":"惡化","original_example":"The drought exacerbated hunger.","original_example_zh":"乾旱加劇了飢荒。"},{"source_id":2556,"word":"exemplify","meaning":"例證","example":"The students' shared effort will exemplify the value of teamwork.","example_zh":"學生共同的努力將展現團隊合作的價值。","original_meaning":"例證","original_example":"This exemplifies the point.","original_example_zh":"這正說明了這一點。"},{"source_id":2557,"word":"exempt","meaning":"免除的","example":"Students with an injured leg are exempt from the running activity.","example_zh":"腿部受傷的學生可以免參加跑步活動。","original_meaning":"免除的","original_example":"Tax exempt.","original_example_zh":"免稅。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-humanitarian-01-v1","level":"senior","word":"humanitarian","sort_order":1,"sense":"人道的","alt_zh":"兩名高中志工在水災後的救援站，把飲水與毛毯交給長者。","example":"The students collected blankets and clean water for a humanitarian relief effort.","example_zh":"學生募集毛毯與乾淨飲水，投入人道救援工作。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/humanitarian-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-illusion-01-v1","level":"senior","word":"illusion","sort_order":1,"sense":"幻覺","alt_zh":"高中生站在鏡子展間，看著反射出的無限長廊。","example":"The mirrors created the illusion of a hallway that never ended.","example_zh":"鏡子營造出走廊永無盡頭的錯覺。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/illusion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-immune-01-v1","level":"senior","word":"immune","sort_order":1,"sense":"免疫的","alt_zh":"高中生觀察透明人體模型，模型中白色免疫細胞包圍綠色病菌。","example":"The classroom model shows how immune cells defend the body against germs.","example_zh":"教室裡的模型展示免疫細胞如何保護身體、抵禦病菌。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immune-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-implicit-01-v1","level":"senior","word":"implicit","sort_order":1,"sense":"隱含的","alt_zh":"兩名高中跑者交換眼神後，一起放慢腳步支持疲憊的隊友。","example":"Without speaking, the teammates shared an implicit agreement to help the tired runner.","example_zh":"隊友沒有說話，卻默契十足地一起幫助疲憊的跑者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/implicit-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-impulse-01-v1","level":"senior","word":"impulse","sort_order":1,"sense":"衝動","alt_zh":"高中女生把手從商店裡的可愛玩具旁收回，將硬幣放回錢包。","example":"Mina resisted the impulse to buy another toy and saved her money instead.","example_zh":"米娜忍住再買一個玩具的衝動，把錢存了起來。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impulse-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-incentive-01-v1","level":"senior","word":"incentive","sort_order":1,"sense":"激勵","alt_zh":"高中生看著剛收成的蔬菜籃，開心地繼續澆灌校園菜園。","example":"A basket of fresh vegetables gave the students an incentive to care for the garden.","example_zh":"一籃新鮮蔬菜讓學生更有動力照顧菜園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/incentive-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-induce-01-v1","level":"senior","word":"induce","sort_order":1,"sense":"引起","alt_zh":"高中生走過麵包店，聞到剛出爐的麵包香後摸著肚子。","example":"The smell of freshly baked bread can induce a feeling of hunger.","example_zh":"剛出爐麵包的香味可能引起飢餓感。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/induce-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inferior-01-v1","level":"senior","word":"inferior","sort_order":1,"sense":"低等的","alt_zh":"老師在實驗桌示範兩條繩子承受相同砝碼，一條斷裂而另一條完整。","example":"The inferior rope snapped while the stronger rope held the same weight.","example_zh":"品質較差的繩子斷了，較結實的繩子卻承受住相同重量。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inferior-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inflation-01-v1","level":"senior","word":"inflation","sort_order":1,"sense":"通貨膨脹","alt_zh":"攤販前的高中生拿著硬幣和兩顆蘋果，旁邊舊照片中相同硬幣能買四顆蘋果。","example":"Because of inflation, the same coins bought fewer apples this year.","example_zh":"因為通貨膨脹，今年相同的硬幣只能買到較少的蘋果。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inflation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inhabit-01-v1","level":"senior","word":"inhabit","sort_order":1,"sense":"居住","alt_zh":"高中生在池塘邊觀察水中的魚、青蛙和水生昆蟲。","example":"Many small creatures inhabit the pond behind our school.","example_zh":"許多小生物住在學校後方的池塘裡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inhabit-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inherent-01-v1","level":"senior","word":"inherent","sort_order":1,"sense":"固有的","alt_zh":"嚮導在安全地點向高中健行隊指著陡峭山坡、碎石與落差。","example":"The guide explained the inherent risks of climbing a steep mountain.","example_zh":"嚮導解釋攀登陡峭山峰本身就有的風險。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inherent-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inherit-01-v1","level":"senior","word":"inherit","sort_order":1,"sense":"繼承","alt_zh":"祖父鄭重把老提琴交給高中孫子，兩人微笑看著樂器。","example":"Leo will inherit his grandfather's old violin and keep playing it.","example_zh":"里歐將繼承祖父的老提琴，並繼續拉奏它。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inherit-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-initiate-01-v1","level":"senior","word":"initiate","sort_order":1,"sense":"發起","alt_zh":"高中社團成員在池塘旁首次集合，領隊遞出工具並展開復育工作。","example":"The science club will initiate a project to restore the school pond.","example_zh":"科學社將發起修復校園池塘的計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/initiate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-injustice-01-v1","level":"senior","word":"injustice","sort_order":1,"sense":"不公","alt_zh":"高中生伸手邀請被排除在小組外的新同學加入，老師在旁支持。","example":"The students spoke out against the injustice of excluding their new classmate.","example_zh":"學生發聲反對排擠新同學的不公平行為。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/injustice-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inspect-01-v1","level":"senior","word":"inspect","sort_order":1,"sense":"檢查","alt_zh":"高中生在老師指導下仔細檢查腳踏車的煞車線與煞車把手。","example":"Before the trip, we inspect every bicycle for loose brakes.","example_zh":"旅行前，我們檢查每輛腳踏車的煞車是否鬆動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inspect-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-institute-01-v1","level":"senior","word":"institute","sort_order":1,"sense":"機構","alt_zh":"高中生跟著海洋科學家參觀有海水樣本與水下機器人的研究室。","example":"Our class visited a research institute to learn how scientists study the ocean.","example_zh":"我們班參訪研究機構，了解科學家如何研究海洋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/institute-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-intact-01-v1","level":"senior","word":"intact","sort_order":1,"sense":"完整的","alt_zh":"高中女生從壓凹的紙箱與保護紙中，取出完整的玻璃花瓶。","example":"Although the box was crushed, the glass vase inside remained intact.","example_zh":"雖然箱子被壓扁，裡面的玻璃花瓶仍完好無損。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/intact-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-intellect-01-v1","level":"senior","word":"intellect","sort_order":1,"sense":"智力","alt_zh":"高中生專注合作解開桌上複雜的立體木製益智拼圖。","example":"Solving the difficult puzzle challenged everyone's intellect.","example_zh":"解開這道難題考驗了每個人的智力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/intellect-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-intensify-01-v1","level":"senior","word":"intensify","sort_order":1,"sense":"加劇","alt_zh":"高中生在堅固屋簷下看著樹枝大幅搖擺、烏雲逼近。","example":"Dark clouds gathered as the wind began to intensify.","example_zh":"烏雲聚集，風也開始增強。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/intensify-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-interfere-01-v1","level":"senior","word":"interfere","sort_order":1,"sense":"干涉","alt_zh":"高中生伸手想碰正在修理的精密模型，另一名學生輕聲示意等候。","example":"Please do not interfere while the technician repairs the delicate model.","example_zh":"技師修理精密模型時，請不要干擾。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/interfere-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-intervene-01-v1","level":"senior","word":"intervene","sort_order":1,"sense":"介入","alt_zh":"老師走到兩名爭執的高中生之間，平靜地讓雙方停下並傾聽。","example":"The teacher had to intervene when the argument became too heated.","example_zh":"爭論越來越激烈，老師不得不介入。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/intervene-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-intimate-01-v1","level":"senior","word":"intimate","sort_order":1,"sense":"親密的","alt_zh":"家人圍坐在小咖啡館的溫暖角落，靠近彼此、專注交談。","example":"The small café was an intimate setting for a quiet family conversation.","example_zh":"這間小咖啡館適合一家人親密而安靜地談話。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/intimate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-invade-01-v1","level":"senior","word":"invade","sort_order":1,"sense":"入侵；闖入","alt_zh":"高中生在蔬菜園邊搭好低柵欄，幾隻兔子停在柵欄外。","example":"We built a fence to keep rabbits from trying to invade the vegetable garden.","example_zh":"我們圍起柵欄，防止兔子闖入菜園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/invade-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-inventory-01-v1","level":"senior","word":"inventory","sort_order":1,"sense":"庫存","alt_zh":"高中志工逐一清點架上罐頭與米袋，再放入捐贈紙箱。","example":"The volunteers checked the inventory before packing the food boxes.","example_zh":"志工在裝食物箱前先清點庫存。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inventory-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-ironic-01-v1","level":"senior","word":"ironic","sort_order":1,"sense":"諷刺的","alt_zh":"滿是雨傘的商店裡，店主無奈地用水桶接屋頂滴下的雨水。","example":"It was ironic that the umbrella shop had a leaking roof.","example_zh":"賣傘的店竟然屋頂漏水，真是諷刺。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ironic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-keen-01-v1","level":"senior","word":"keen","sort_order":1,"sense":"渴望的","alt_zh":"高中女生提早坐在陶輪前，興奮地看著老師示範陶土工具。","example":"Nora was keen to learn pottery and arrived before the class began.","example_zh":"諾拉很渴望學陶藝，課程開始前就到了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/keen-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-landmark-01-v1","level":"senior","word":"landmark","sort_order":1,"sense":"地標","alt_zh":"高中生在城鎮廣場向遊客指著高聳醒目的老鐘樓。","example":"The old clock tower is a landmark that helps visitors find the town square.","example_zh":"老鐘樓是地標，幫助遊客找到城鎮廣場。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/landmark-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-legislation-01-v1","level":"senior","word":